files.content:
* {
  box-sizing: border-box;
  margin: 0;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-width: 850px;
  min-height: 100vh;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #feafe8;
}

.cat-title {
  margin-bottom: 30px;
  font-size: 1.5rem;
}

.text-box {
  padding: 2.5%;
  border-right: 1px solid #000;
  background-color: #ffc802;
}

.parent {
  display: flex;
  width: 1280px;
  margin: 0 50px;
  border: 1px solid #000;
}

.cat-image {
  width: 50%;

}
